solution:
def stock(entries):
    totals = {}
    for item, qty in entries:
        totals[item] = totals.get(item, 0) + qty
    return {item: n for item, n in totals.items() if n != 0}

alt:
def stock(entries):
    totals = {}
    for item, qty in entries:
        if item in totals:
            totals[item] += qty
        else:
            totals[item] = qty
    return {k: v for k, v in totals.items() if v}
